import requests
from typing import Optional, Dict, Any

class BytecodeToOpcodeConverter:
    """
    A class to convert Ethereum transaction bytecode to opcode using Etherscan's API.
    """

    def __init__(self, api_key: str):
        """
        Initialize the converter with an Etherscan API key.

        Args:
            api_key: Etherscan API key for making requests.
        """
        self.api_key = api_key
        self.base_url = "https://api.etherscan.io/api"

    def convert_bytecode_to_opcode(self, bytecode: str) -> Optional[str]:
        """
        Convert Ethereum bytecode to opcode using Etherscan's API.

        Args:
            bytecode: The bytecode to convert.

        Returns:
            The opcode as a string if successful, None otherwise.
        """
        params = {
            "module": "contract",
            "action": "getopcodes",
            "bytecode": bytecode,
            "apikey": self.api_key
        }

        try:
            response = requests.get(self.base_url, params=params)
            response.raise_for_status()
            data = response.json()

            if data["status"] == "1" and data["message"] == "OK":
                return data["result"]
            else:
                print(f"Error from Etherscan API: {data.get('message', 'Unknown error')}")
                return None

        except requests.exceptions.RequestException as e:
            print(f"Request failed: {e}")
            return None
        except ValueError as e:
            print(f"Failed to parse response: {e}")
            return None

